    highp float exp = floor(log2(z)); 
\
    highp float m = z * 16.0 / pow(2.0, exp) - 16.0; 
\
    lowp float idx = floor(m) + exp * 16.0 + 0.5; 
\
    highp vec4 fog_coef = texture(fog_table, vec2(idx / 128.0, 0.75 - (m - floor(m)) / 2.0)); 
\
    return fog_coef.FOG_CHANNEL; 
\
} 
