wchar* trim_ws(wchar* str)
{
    if (str==0 || strlen(str)==0)
        return 0;

    while(*str)
    {
        if (!isspace(*str))
            break;
        str++;
    }

    size_t l=strlen(str);

    if (l==0)
        return 0;

    while(l>0)
    {
        if (!isspace(str[l-1]))
            break;
        str[l-1]=0;
        l--;
    }

    if (l==0)
        return 0;

    union
    {
        u32 full;
        struct
        {
            u32 RM:2;
            u32 finexact:1;
            u32 funderflow:1;
            u32 foverflow:1;
            u32 fdivbyzero:1;
            u32 finvalidop:1;
            u32 einexact:1;
            u32 eunderflow:1;
            u32 eoverflow:1;
            u32 edivbyzero:1;
            u32 einvalidop:1;
            u32 cinexact:1;
            u32 cunderflow:1;
            u32 coverflow:1;
            u32 cdivbyzero:1;
            u32 cinvalid:1;
            u32 cfpuerr:1;
            u32 DN:1;
            u32 PR:1;
            u32 SZ:1;
            u32 FR:1;
        };
        struct
        {
            u32 nil:2+1+1+1+1+4+8+1;
            u32 PR_SZ:2;
        };
    };
};

