//fcnvds <DR_N>,FPUL
sh4op(i1111_nnnn_1011_1101)
{

    if (fpscr.PR == 1)
    {
        u32 n = (op >> 9) & 0x07;
        u32*p=&fpul;
        *((float*)p) = (float)GetDR(n);
    }
    else
    {
        iNimp("fcnvds <DR_N>,FPUL,m=0");
    }
}

//fcnvsd FPUL,<DR_N>
sh4op(i1111_nnnn_1010_1101)
{
    if (fpscr.PR == 1)
    {
        u32 n = (op >> 9) & 0x07;
        u32* p = &fpul;
        SetDR(n,(double)*((float*)p));
    }
    else
    {
        iNimp("fcnvsd FPUL,<DR_N>,m=0");
    }
}

//float FPUL,<FREG_N>
sh4op(i1111_nnnn_0010_1101)
{
    if (fpscr.PR == 0)
    {
        u32 n = GetN(op);
        fr[n] = (float)(int)fpul;
    }
    else
    {
        u32 n = (op >> 9) & 0x07;
        SetDR(n, (double)(int)fpul);
    }
}

