//mov.l @(<disp>,<REG_M>),<REG_N>
sh4op(i0101_nnnn_mmmm_iiii)
{
    u32 n = GetN(op);
    u32 m = GetM(op);
    u32 disp = GetImm4(op) << 2;

    ReadMemBOU32(r[n],r[m],disp);
}

